ull, "status": "draft", "id": "1ff37b26-7a3f-5d5e-9006-9364737e05b2"}, {"title": "明廷督促百姓种桑枣和木棉", "description": "朝廷督促百姓种植桑、枣和木棉。", "start_year": 1394, "end_year": 1394, "time_original": "洪武二十七年三月庚戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "989519fd-8f0f-519b-8722-8c0aac8ccf38"}, {"title": "明廷以四方已定为由收存甲兵", "description": "朝廷以四方安定为由收存铠甲兵器，表示不再动用。", "start_year": 1394, "end_year": 1394, "time_original": "洪武二十七年三月甲子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "59e27a3e-0080-58a9-b147-6ceef2bf2cec"}, {"title": "吴杰和张铨率退休武官赴广东防倭", "description": "吴杰与永定侯张铨率已经退休的武官在广东部署防倭。", "start_year": 1394, "end_year": 1394, "time_original": "洪武二十七年八月甲戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e015b63d-f5c1-53a3-8bac-1ae043fe65b8"}, {"title": "明廷分派国子监生督修水利", "description": "朝廷将国子监生分派到各地，督促地方官吏和百姓兴修水利。", "start_year": 1394, "end_year": 1394, "time_original": "洪武二十七年八月乙亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "169871cf-b0b1-5277-b24e-0af2f25a76c3"}, {"title": "甯正奉命平定阶文军乱", "description": "阶、文两地发生军乱，朝廷任命都督甯正为平羌将军，率兵出讨。", "start_year": 1394, "end_year": 1394, "time_original": "洪武二十七年八月丙戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4514c699-e229-5fc6-b721-83806e9f559e"}, {"title": "徐辉祖节制陕西沿边各军", "description": "徐辉祖统领陕西沿边各军。", "start_year": 1394, "end_year": 1394, "time_original": "洪武二十七年九月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e30c3e3d-63b8-5939-97d8-a3cbf39b10da"}, {"title": "颍国公傅友德被处死", "description": "颍国公傅友德获罪被处死。本纪这一段未列具体罪名。", "start_year": 1394, "end_year": 1394, "time_original": "洪武二十七年十一月乙丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "470d35bf-1de8-58c8-bed5-bd8b10ccbdc2"}, {"title": "阿资再次起兵，沐春击败对方", "description": "阿资再次起兵反明，西平侯沐春率军击败阿资。", "start_year": 1394, "end_year": 1394, "time_original": "洪武二十七年十一月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6ca38bd0-99bb-5fb4-a338-04d12539a37a"}, {"title": "定远侯王弼被处死", "description": "定远侯王弼获罪被处死，本纪这一段未列具体罪名。", "start_year": 1395, "end_year": 1395, "time_original": "洪武二十七年十二月乙亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6000f9d6-5585-55e2-b95a-ba372059c58d"}, {"title": "乌斯藏等地来贡，明廷拒收安南贡品", "description": "本纪列出乌斯藏、琉球、缅、朵甘、爪哇、撒马儿罕和朝鲜入贡，并记明廷拒收安南来贡。 按原历纪年，事情发生在公元1394至1395年之间。", "start_year": null, "end_year": null, "time_original": "洪武二十七年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "88e2b495-f668-58e3-ab2e-a3176bfc5ebd"}, {"title": "阶文战事平定后甯正随秦王出兵洮州", "description": "阶、文战事平定后，甯正率兵随秦王朱樉出讨洮州。", "start_year": 1395, "end_year": 1395, "time_original": "洪武二十八年正月丙午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "351fc25d-9541-5f21-9fd3-8cfebd271e4b"}, {"title": "明廷在南郊祭祀天地", "description": "明廷在南郊举行祭祀天地的大礼。", "start_year": 1395, "end_year": 1395, "time_original": "洪武二十八年正月丁未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ec9ccc34-453c-5612-910c-4fbc659a56c2"}, {"title": "沐春擒斩阿资后越州平定", "description": "西平侯沐春率军擒获并处死阿资，越州战事平定。", "start_year": 1395, "end_year": 1395, "time_original": "洪武二十八年正月甲子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "cf66ebb6-3b02-5c9a-abc9-d080070b7900"}, {"title": "周王和晋王率所部出塞筑城屯田", "description": "周王朱橚和晋王朱棡率河南、山西各卫军士出塞，筑城屯田。", "start_year": 1395, "end_year": 1395, "time_original": "洪武二十八年正月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a16ab207-28c8-5447-864e-9861da798f71"}, {"title": "燕王朱棣率周兴出辽东边塞", "description": "燕王朱棣率总兵官周兴出辽东边塞。", "start_year": 1395, "end_year": 1395, "time_original": "洪武二十八年正月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "dbc7c615-3f79-5489-98c7-a1d11c8b78d7"}, {"title": "宋国公冯胜被处死", "description": "宋国公冯胜获罪被处死。本纪这一段未列具体罪名。", "start_year": 1395, "end_year": 1395, "time_original": "洪武二十八年二月丁卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "56fb7301-2fec-50a7-b6b4-e994c263e235"}, {"title": "明廷令户部编百户为里并鼓励乡里互助", "description": "朝廷命户部以一百户编为一里。遇婚丧、疾病和患难，富户出财，贫户出力。春耕秋收互相合作，使乡里和睦。", "start_year": 1395, "end_year": 1395, "time_original": "洪武二十八年二月己丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d9a57d12-8cc2-55dc-854f-93183534a6fe"}, {"title": "明廷命诸土司设立儒学", "description": "朝廷下诏，各土司都要设立儒学。", "start_year": 1395, "end_year": 1395, "time_original": "洪武二十八年六月壬申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0fcc329c-3043-5304-ada2-307edf2869b6"}, {"title": "周兴等追敌至甫答迷城后返回", "description": "周兴等自开原追至甫答迷城，未追上对方，随后返回。", "start_year": 1395, "end_year": 1395, "time_original": "洪武二十八年六月辛巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "835f460f-e47d-5888-9a0b-fcd722b745f8"}, {"title": "朱元璋规定后世禁用若干刑罚", "description": "朱元璋训示，后继者应遵循法律和《大诰》，禁用黥刺、剕、劓和阉割。臣下请求使用这些刑罚的，从重治罪。", "start_year": 1395, "end_year": 1395, "time_original": "洪武二十八年六月己丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "fd4d0d84-22fa-5eb7-854e-5d98dd891235"}, {"title": "朱元璋训示后世不得恢复丞相", "description": "朱元璋对群臣说，罢去丞相后由府、部、都察院分理政务，事权归朝廷。并规定继位君主不得再设丞相。", "start_year": 1395, "end_year": 1395, "time_original": "洪武二十八年六月己丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d8e5c12a-898e-5ac4-b854-da2ca4fd037d"}, {"title": "朱元璋规定皇亲案件的处理办法", "description": "朱元璋训示，皇亲谋逆不赦。其他罪行由宗亲会商，请皇帝裁决。主管司法的官署只能举奏，不得擅自逮捕。", "start_year": 1395, "end_year": 1395, "time_original": "洪武二十八年六月己丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7078b439-3bcb-5e26-bd74-1d9be0daa7ef"}, {"title": "杨文韩观宋晟奉命出兵龙州", "description": "朝廷任都督杨文为征南将军，指挥韩观和都督佥事宋晟为副将，率军讨伐龙州土官赵宗寿。", "start_year": 1395, "end_year": 1395, "time_original": "洪武二十八年八月丁卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "756f990c-1e80-57f1-a8f5-0920563c7f35"}, {"title": "信国公汤和去世", "description": "信国公汤和在八月戊辰去世。", "start_year": 1395, "end_year": 1395, "time_original": "洪武二十八年八月戊辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "87445258-0c96-5a71-8e5f-ebcaed68455c"}, {"title": "赵宗寿入朝请罪，杨文移兵奉议南丹", "description": "赵宗寿入朝请罪，杨文率军改赴奉议、南丹征讨。", "start_year": 1395, "end_year": 1395, "time_original": "洪武二十八年八月辛巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "074b1224-fc1b-5e69-93e9-60da2265eb6d"}, {"title": "明廷免征畿内山东秋粮", "description": "朝廷免去畿内和山东的秋粮。", "start_year": 1395, "end_year": 1395, "time_original": "洪武二十八年九月丁酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b5596a68-d3cc-504e-896f-4abc372f8132"}, {"title": "明廷公布《皇明祖训》条章", "description": "明廷向中央和地方颁布《皇明祖训》条章，规定后世有人提议更改祖制，以奸臣论处。", "start_year": 1395, "end_year": 1395, "time_original": "洪武二十八年九月庚戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c23e3de1-994a-5e85-afc1-dcc942e213fa"}, {"title": "奉议南丹战事平定", "description": "本纪记载，奉议、南丹的战事在十一月乙亥全部平定。", "start_year": 1396, "end_year": 1396, "time_original": "洪武二十八年十一月乙亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0b96fc7e-15b5-553f-904e-46532aeaddfd"}, {"title": "明廷下令免征河南山东桑枣及部分新垦田税", "description": "朝廷下诏，河南、山东的桑枣及洪武二十七年以后的新垦田免征税。", "start_year": 1396, "end_year": 1396, "time_original": "洪武二十八年十二月壬辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5fc1d878-9fb1-58b2-b305-133733d5cb77"}, {"title": "朝鲜琉球暹罗来贡", "description": "本纪记载，朝鲜、琉球和暹罗于当年来贡。 按原历纪年，事情发生在公元1395至1396年之间。", "start_year": null, "end_year": null, "time_original": "洪武二十八年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "df0cdf18-b1d8-5708-99d6-a7afd52ba33a"}, {"title": "明廷在南郊祭祀天地", "description": "明廷在南郊举行祭祀天地的大礼。", "start_year": 1396, "end_year": 1396, "time_original": "洪武二十九年正月壬申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b08fe239-6bfe-5492-983a-2102ccd41a6b"}, {"title": "胡冕平定郴桂战事", "description": "征虏前将军胡冕出兵平定郴、桂的战事。", "start_year": 1396, "end_year": 1396, "time_original": "洪武二十九年二月癸卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "81379f81-ca3a-5493-9f0e-bfd2f767b06e"}, {"title": "燕王巡视大宁，周世子巡视北平关隘", "description": "燕王朱棣率军巡视大宁，周世子朱有燉率军巡视北平关隘。", "start_year": 1396, "end_year": 1396, "time_original": "洪武二十九年二月辛亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c77582a7-89d3-5c3e-9a48-61bd30adb2b3"}, {"title": "楚王朱桢和湘王朱柏来朝", "description": "楚王朱桢、湘王朱柏于三月辛酉入朝。", "start_year": 1396, "end_year": 1396, "time_original": "洪武二十九年三月辛酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f16f3a33-0887-5a84-8c64-5717162a95c0"}, {"title": "燕王军在彻彻儿山和兀良哈秃城获胜", "description": "燕王朱棣在彻彻儿山击败敌军，又追至兀良哈秃城再度获胜，随后率军返回。", "start_year": 1396, "end_year": 1396, "time_original": "洪武二十九年三月甲子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2c6c6aaf-f021-575c-9982-957d5ace8da7"}, {"title": "明廷免征应天等五府田租", "description": "朝廷免去应天、太平等五府的田租。", "start_year": 1396, "end_year": 1396, "time_original": "洪武二十九年八月丁未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a237b4f6-3038-5b01-a74c-cb0c921a5458"}, {"title": "明廷召退休武官入朝并赏赐晋级", "description": "朝廷召来两千五百多名退休武臣入朝，厚加赏赐，并分别晋升一等品秩。", "start_year": 1396, "end_year": 1396, "time_original": "洪武二十九年九月乙亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a4ab6e17-6e43-5cfb-a2c5-2bd83e0301dc"}, {"title": "琉球等地来贡", "description": "本纪记载，琉球、安南、朝鲜和乌斯藏在这一年入贡。 按原历纪年，事情发生在公元1396至1397年之间。", "start_year": null, "end_year": null, "time_original": "洪武二十九年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "10cb2839-2887-5d6b-a895-ad3c6ff68e66"}]'::jsonb)
